package org.opensourcepingpong.competition;

import jakarta.validation.Valid;
import java.time.Instant;
import java.sql.Timestamp;
import java.sql.Types;
import java.util.*;
import org.opensourcepingpong.auth.AuthPrincipal;
import org.opensourcepingpong.common.api.*;
import org.opensourcepingpong.organization.*;
import org.opensourcepingpong.rating.RatingSettlementService;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;

@RestController
@RequestMapping("/api/v1")
public class CompetitionController {
  private final JdbcTemplate jdbc; private final AuthorizationService auth; private final ScheduleService schedules; private final RatingSettlementService ratings;
  public CompetitionController(JdbcTemplate jdbc, AuthorizationService auth, ScheduleService schedules, RatingSettlementService ratings){this.jdbc=jdbc;this.auth=auth;this.schedules=schedules;this.ratings=ratings;}
  @GetMapping("/competitions") ApiResponse<?> list(){return ApiResponse.ok(jdbc.queryForList("select id,title,competition_type,format,status,location,registration_end,start_time from competitions order by created_at desc"));}
  @GetMapping("/competitions/{id}") ApiResponse<?> detail(@PathVariable UUID id){var rows=jdbc.queryForList("select * from competitions where id=?",id);if(rows.isEmpty())throw missing();return ApiResponse.ok(rows.getFirst());}
  @PostMapping("/admin/competitions") ApiResponse<Map<String,UUID>> create(@AuthenticationPrincipal AuthPrincipal p,@Valid @RequestBody Create r){
    auth.require(p.userId(),Permission.COMPETITION_CREATE); validate(r);
    UUID id=UUID.randomUUID();
    jdbc.update("insert into competitions(id,title,description,competition_type,event_type,format,status,registration_scope,registration_requires_review,max_participants,best_of,location,registration_start,registration_end,start_time,creator_user_id) values(?,?,?,?,?,?,'DRAFT',?,?,?,?,?,?,?,?,?)", ps->{ps.setObject(1,id);ps.setString(2,r.title());if(r.description()==null)ps.setNull(3,Types.VARCHAR);else ps.setString(3,r.description());ps.setString(4,r.type().name());ps.setString(5,"SINGLES");ps.setString(6,r.format().name());ps.setString(7,r.scope());ps.setBoolean(8,r.review());ps.setInt(9,r.maxParticipants());ps.setInt(10,r.bestOf());ps.setString(11,r.location());ps.setTimestamp(12,Timestamp.from(r.registrationStart()));ps.setTimestamp(13,Timestamp.from(r.registrationEnd()));ps.setTimestamp(14,Timestamp.from(r.startTime()));ps.setObject(15,p.userId());});
    return ApiResponse.ok(Map.of("id",id));
  }
  @PostMapping("/admin/competitions/{id}/publish") ApiResponse<Void> publish(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){transition(p.userId(),id,"publish");return ApiResponse.ok(null);}
  @Transactional @PostMapping("/admin/competitions/{id}/close-registration") ApiResponse<Void> close(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){auth.require(p.userId(),Permission.COMPETITION_MANAGE);var rows=jdbc.queryForList("select status from competitions where id=? for update",id);if(rows.isEmpty())throw missing();CompetitionStateMachine.next(CompetitionStatus.valueOf((String)rows.getFirst().get("status")),"close");Integer approved=jdbc.queryForObject("select count(*) from competition_entries where competition_id=? and status='APPROVED'",Integer.class,id);if(approved==null||approved<2)throw new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY,"COMPETITION_INSUFFICIENT_PARTICIPANTS","at least two approved participants required");jdbc.update("update competitions set status='ARRANGING',updated_at=? where id=?",Timestamp.from(Instant.now()),id);return ApiResponse.ok(null);}
  @PutMapping("/admin/competitions/{id}") ApiResponse<Void> update(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id,@Valid @RequestBody Create r){auth.require(p.userId(),Permission.COMPETITION_MANAGE);validate(r);var rows=jdbc.queryForList("select status from competitions where id=?",id);if(rows.isEmpty())throw missing();String status=(String)rows.getFirst().get("status");if(!Set.of("DRAFT","REGISTRATION").contains(status))throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_INVALID_STATE","competition cannot be edited");jdbc.update("update competitions set title=?,description=?,competition_type=?,format=?,registration_scope=?,registration_requires_review=?,max_participants=?,best_of=?,location=?,registration_start=?,registration_end=?,start_time=?,updated_at=?,version=version+1 where id=?",r.title(),r.description(),r.type().name(),r.format().name(),r.scope(),r.review(),r.maxParticipants(),r.bestOf(),r.location(),Timestamp.from(r.registrationStart()),Timestamp.from(r.registrationEnd()),Timestamp.from(r.startTime()),Timestamp.from(Instant.now()),id);return ApiResponse.ok(null);}
  @PostMapping("/admin/competitions/{id}/arrange") ApiResponse<Void> arrange(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id,@RequestBody(required=false) Map<String,Long> body){schedules.arrange(p.userId(),id,body==null?System.currentTimeMillis():body.getOrDefault("seed",System.currentTimeMillis()));return ApiResponse.ok(null);}
  @GetMapping("/admin/competitions/{id}/arrangement-preview") ApiResponse<?> preview(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id,@RequestParam long seed){return ApiResponse.ok(schedules.preview(p.userId(),id,seed));}
  @PostMapping("/admin/competitions/{id}/start") ApiResponse<Void> start(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){schedules.start(p.userId(),id);return ApiResponse.ok(null);}
  @PostMapping("/admin/competitions/{id}/enter-result-confirming") ApiResponse<Void> confirming(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){schedules.confirming(p.userId(),id);return ApiResponse.ok(null);}
  @PostMapping("/admin/competitions/{id}/finalize") ApiResponse<Void> finalizeCompetition(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){ratings.finalizeCompetition(p.userId(),id);return ApiResponse.ok(null);}
  @PostMapping("/admin/competitions/{id}/cancel") ApiResponse<Void> cancel(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){transition(p.userId(),id,"cancel");return ApiResponse.ok(null);}
  @GetMapping("/competitions/{id}/schedule") ApiResponse<?> schedule(@PathVariable UUID id){return ApiResponse.ok(jdbc.queryForList("select id,round_number,match_number,group_id,status,player_a_user_id,player_b_user_id,winner_user_id,result_type,player_a_games,player_b_games,best_of,version from matches where competition_id=? order by round_number,match_number",id));}
  @GetMapping("/competitions/{id}/bracket") ApiResponse<?> bracket(@PathVariable UUID id){return ApiResponse.ok(jdbc.queryForList("select id,round_number,match_number,status,player_a_user_id,player_b_user_id,winner_user_id,next_match_id,winner_to_slot from matches where competition_id=? and group_id is null order by round_number,match_number",id));}
  @GetMapping("/competitions/{id}/groups") ApiResponse<?> groups(@PathVariable UUID id){return ApiResponse.ok(jdbc.queryForList("select g.id,g.name,g.group_order,gm.user_id,gm.position from competition_groups g join competition_stages s on s.id=g.stage_id left join competition_group_members gm on gm.group_id=g.id where s.competition_id=? order by g.group_order,gm.position",id));}
  @Transactional @PostMapping("/competitions/{id}/entries") ApiResponse<Void> enter(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){var c=jdbc.queryForList("select status,max_participants,registration_requires_review,registration_start,registration_end,registration_scope from competitions where id=? for update",id);if(c.isEmpty())throw missing();var row=c.getFirst();if(!"REGISTRATION".equals(row.get("status")))throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_REGISTRATION_CLOSED","registration is closed");Instant now=Instant.now();if((row.get("registration_start")!=null&&now.isBefore(((Timestamp)row.get("registration_start")).toInstant()))||(row.get("registration_end")!=null&&!now.isBefore(((Timestamp)row.get("registration_end")).toInstant())))throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_REGISTRATION_CLOSED","outside registration window");if("MEMBERS_ONLY".equals(row.get("registration_scope"))){Integer active=jdbc.queryForObject("select count(*) from memberships where user_id=? and status='ACTIVE'",Integer.class,p.userId());if(active==null||active==0)throw new BusinessException(HttpStatus.FORBIDDEN,"PERMISSION_DENIED","active membership required");}Integer count=jdbc.queryForObject("select count(*) from competition_entries where competition_id=? and status in ('PENDING','APPROVED')",Integer.class,id);if(count!=null&&count>=((Number)row.get("max_participants")).intValue())throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_FULL","competition is full");try{boolean review=(Boolean)row.get("registration_requires_review");jdbc.update("insert into competition_entries(id,competition_id,user_id,status,registered_at)values(?,?,?,?,?)",ps->{ps.setObject(1,UUID.randomUUID());ps.setObject(2,id);ps.setObject(3,p.userId());ps.setString(4,review?"PENDING":"APPROVED");ps.setTimestamp(5,Timestamp.from(now));});}catch(DuplicateKeyException e){throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_ALREADY_REGISTERED","already registered");}return ApiResponse.ok(null);}
  @DeleteMapping("/competitions/{id}/entries/me") ApiResponse<Void> leave(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){var c=jdbc.queryForList("select status from competitions where id=?",id);if(c.isEmpty())throw missing();if(!"REGISTRATION".equals(c.getFirst().get("status")))throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_REGISTRATION_CLOSED","registration is closed");int changed=jdbc.update("delete from competition_entries where competition_id=? and user_id=? and status in ('PENDING','APPROVED')",id,p.userId());if(changed!=1)throw new BusinessException(HttpStatus.NOT_FOUND,"ENTRY_NOT_FOUND","entry not found");return ApiResponse.ok(null);}
  @GetMapping("/competitions/{id}/entries/me") ApiResponse<?> myEntry(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){
    if(p==null)return ApiResponse.ok(null);
    var rows=jdbc.queryForList("select e.id,e.competition_id,e.user_id,e.status,e.seed_number,e.registered_at,e.approved_at from competition_entries e where e.competition_id=? and e.user_id=?",id,p.userId());
    return ApiResponse.ok(rows.isEmpty()?null:rows.getFirst());
  }
  @GetMapping("/admin/competitions/{id}/entries") ApiResponse<?> entries(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){auth.require(p.userId(),Permission.COMPETITION_MANAGE);return ApiResponse.ok(jdbc.queryForList("select e.id,e.user_id,e.status,e.seed_number,e.registered_at,e.approved_at,p.nickname,p.real_name from competition_entries e left join user_profiles p on p.user_id=e.user_id where e.competition_id=? order by e.registered_at",id));}
  @PostMapping("/admin/competition-entries/{entryId}/approve") ApiResponse<Void> approveEntry(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID entryId){reviewEntry(p.userId(),entryId,true);return ApiResponse.ok(null);}
  @PostMapping("/admin/competition-entries/{entryId}/reject") ApiResponse<Void> rejectEntry(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID entryId){reviewEntry(p.userId(),entryId,false);return ApiResponse.ok(null);}
  private void transition(UUID user,UUID id,String action){auth.require(user,Permission.COMPETITION_MANAGE);var rows=jdbc.queryForList("select status from competitions where id=?",id);if(rows.isEmpty())throw missing();CompetitionStatus to=CompetitionStateMachine.next(CompetitionStatus.valueOf((String)rows.getFirst().get("status")),action);jdbc.update("update competitions set status=? where id=?",to.name(),id);}
  private void reviewEntry(UUID user,UUID entryId,boolean approve){auth.require(user,Permission.COMPETITION_MANAGE);var rows=jdbc.queryForList("select e.status,c.status competition_status from competition_entries e join competitions c on c.id=e.competition_id where e.id=?",entryId);if(rows.isEmpty())throw new BusinessException(HttpStatus.NOT_FOUND,"ENTRY_NOT_FOUND","entry not found");if(!"REGISTRATION".equals(rows.getFirst().get("competition_status"))||!"PENDING".equals(rows.getFirst().get("status")))throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_INVALID_STATE","entry cannot be reviewed");Timestamp now=Timestamp.from(Instant.now());int changed=jdbc.update("update competition_entries e set status=?,approved_at=?,updated_at=? from competitions c where e.id=? and e.status='PENDING' and e.competition_id=c.id and c.status='REGISTRATION'",approve?"APPROVED":"REJECTED",approve?now:null,now,entryId);if(changed!=1)throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_INVALID_STATE","entry already reviewed");}
  private static BusinessException missing(){return new BusinessException(HttpStatus.NOT_FOUND,"COMPETITION_NOT_FOUND","competition not found");}
  private static void validate(Create r){if(r.type()==null||r.format()==null||!(r.bestOf()==3||r.bestOf()==5||r.bestOf()==7)||r.registrationStart()==null||r.registrationEnd()==null||r.startTime()==null||r.scope()==null||!Set.of("PUBLIC","MEMBERS_ONLY").contains(r.scope())||!r.registrationStart().isBefore(r.registrationEnd())||r.registrationEnd().isAfter(r.startTime())||(r.format()==CompetitionFormat.SINGLE_ELIMINATION&&r.maxParticipants()>64))throw new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY,"VALIDATION_ERROR","invalid competition parameters");}
  public record Create(@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=120) String title,String description,CompetitionType type,CompetitionFormat format,@jakarta.validation.constraints.NotBlank String scope,boolean review,@jakarta.validation.constraints.Min(2) int maxParticipants,int bestOf,@jakarta.validation.constraints.NotBlank String location,Instant registrationStart,Instant registrationEnd,Instant startTime){}
}
